package dev.celerbi.easyfarmersdelightcompat.integration.emi;
import dev.celerbi.easyfarmersdelightcompat.integration.FarmerHarvestInfo;import dev.emi.emi.api.recipe.EmiRecipe;import dev.emi.emi.api.recipe.EmiRecipeCategory;import dev.emi.emi.api.render.EmiTexture;import dev.emi.emi.api.stack.EmiIngredient;import dev.emi.emi.api.stack.EmiStack;import dev.emi.emi.api.widget.WidgetHolder;import java.util.ArrayList;import java.util.List;import net.minecraft.resources.ResourceLocation;
public final class FarmerHarvestEmiRecipe implements EmiRecipe{private final FarmerHarvestInfo info;private final EmiStack input;private final EmiIngredient tool;private final List<EmiStack> outputs;public FarmerHarvestEmiRecipe(FarmerHarvestInfo i){info=i;input=EmiStack.of(i.input());tool=EmiIngredient.of(i.tool());outputs=i.outputs().stream().map(EmiStack::of).toList();}public EmiRecipeCategory getCategory(){return EasyFdEmiPlugin.FARMER_HARVEST;}public ResourceLocation getId(){return info.id();}public List<EmiIngredient> getInputs(){List<EmiIngredient> l=new ArrayList<>();l.add(input);l.add(tool);return l;}public List<EmiStack> getOutputs(){return outputs;}public int getDisplayWidth(){return 180;}public int getDisplayHeight(){return 82;}public void addWidgets(WidgetHolder w){w.addSlot(input,8,6);w.addSlot(tool,48,6);w.addTexture(EmiTexture.EMPTY_ARROW,76,6);for(int i=0;i<Math.min(4,outputs.size());i++)w.addSlot(outputs.get(i),108+i*18,6).recipeContext(this);w.addText(info.description(),4,36,0x555555,false);}}
